using EEMS.SharedKernel.Domain;
namespace EEMS.Modules.Inventory.Domain;
public sealed class InventoryItem:Entity<Guid>{private InventoryItem(){}private InventoryItem(Guid id,Guid tenantId,string sku,string name,string unit){if(tenantId==Guid.Empty)throw new ArgumentException("Tenant is required.");Id=id;TenantId=tenantId;Sku=InventoryRules.Text(sku,80);Name=InventoryRules.Text(name,180);Unit=InventoryRules.Text(unit,40);IsActive=true;}public Guid TenantId{get;private set;}public string Sku{get;private set;}=string.Empty;public string Name{get;private set;}=string.Empty;public string Unit{get;private set;}=string.Empty;public bool IsActive{get;private set;}public static InventoryItem Create(Guid tenantId,string sku,string name,string unit)=>new(Guid.NewGuid(),tenantId,sku,name,unit);}
